import {apiClient} from '@common/http/query-client';
import {DashboardLayout} from '@common/ui/dashboard/dashboard-layout';
import {Badge} from '@shadcn/badge/badge';
import {Button} from '@shadcn/button/button';
import {Card} from '@shadcn/card/card';
import {Table} from '@shadcn/table/table';
import {Trans} from '@ui/i18n/trans';
import {ArrowLeftIcon, CheckIcon} from 'lucide-react';
import {useCallback, useEffect, useState} from 'react';
import {Link} from 'react-router';

type Payout = {id: number; amount_cents: number; currency: string; status: string; payout_method_label?: string | null; created_at: string; creator?: {name: string; email: string}};
export function Component() { const [payouts, setPayouts] = useState<Payout[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState<string>(); const [processing, setProcessing] = useState<number>(); const load = useCallback(async () => { setLoading(true); try { const response = await fetch('/api/v1/admin/digital-products/payout-requests', {credentials: 'same-origin', headers: {Accept: 'application/json'}}); if (!response.ok) throw new Error('Unable to load payout requests.'); const payload = await response.json(); setPayouts(payload.data ?? []); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Unable to load payout requests.'); } finally { setLoading(false); } }, []); useEffect(() => { void load(); }, [load]); const markPaid = async (payout: Payout) => { setProcessing(payout.id); try { await apiClient.post(`/api/v1/admin/digital-products/payout-requests/${payout.id}/mark-paid`); await load(); } catch { setError('Unable to mark payout as paid.'); } finally { setProcessing(undefined); } }; return <DashboardLayout.MainSection><DashboardLayout.SectionHeader><DashboardLayout.SidebarToggle /><div><DashboardLayout.SectionTitle><Trans message="Payout requests" /></DashboardLayout.SectionTitle><p className="mt-0.5 text-sm text-muted-foreground"><Trans message="Record manual payments after you complete them outside Linket." /></p></div><Button variant="outline" render={<Link to="/admin/digital-products" />}><ArrowLeftIcon /><Trans message="Product review" /></Button></DashboardLayout.SectionHeader><DashboardLayout.SectionContent className="overflow-y-auto"><div className="mx-auto w-full max-w-6xl py-6">{error && <div className="mb-5 rounded-input border border-destructive/40 bg-destructive/5 p-3 text-sm text-destructive">{error}</div>}<Card.Root><Card.Content className="overflow-x-auto"><Table.Root><Table.Header><Table.Row><Table.Head><Trans message="Creator" /></Table.Head><Table.Head><Trans message="Withdrawal method" /></Table.Head><Table.Head><Trans message="Requested" /></Table.Head><Table.Head><Trans message="Status" /></Table.Head><Table.Head className="text-end"><Trans message="Action" /></Table.Head></Table.Row></Table.Header><Table.Body>{loading ? <Table.Row><Table.Cell colSpan={5} className="h-28 text-center text-muted-foreground"><Trans message="Loading…" /></Table.Cell></Table.Row> : payouts.length ? payouts.map(payout => <Table.Row key={payout.id}><Table.Cell><p className="font-medium">{payout.creator?.name}</p><p className="text-xs text-muted-foreground">{payout.creator?.email}</p></Table.Cell><Table.Cell className="text-muted-foreground">{payout.payout_method_label ?? <Trans message="Not specified" />}</Table.Cell><Table.Cell>{formatMoney(payout.amount_cents, payout.currency)}</Table.Cell><Table.Cell><Badge color={payout.status === 'paid' ? 'positive' : 'warning'} variant="outline"><Trans message={payout.status} /></Badge></Table.Cell><Table.Cell className="text-end">{payout.status === 'pending' && <Button size="sm" disabled={processing === payout.id} onClick={() => void markPaid(payout)}><CheckIcon /><Trans message="Mark paid" /></Button>}</Table.Cell></Table.Row>) : <Table.Row><Table.Cell colSpan={5} className="h-28 text-center text-muted-foreground"><Trans message="No payout requests." /></Table.Cell></Table.Row>}</Table.Body></Table.Root></Card.Content></Card.Root></div></DashboardLayout.SectionContent></DashboardLayout.MainSection>; }
function formatMoney(cents: number, currency: string) { return new Intl.NumberFormat(undefined, {style: 'currency', currency}).format(cents / 100); }
